  if(!isCurrent()||controller.signal.aborted)return;
  $('.sign-loading',stage).textContent='Motion received. Preparing the player…';
  const objectUrl=URL.createObjectURL(blob);mediaUrls.push(objectUrl);const mount=$('.pose-mount',stage);mount.innerHTML='';
  const viewer=document.createElement('pose-viewer');viewer.setAttribute('src',objectUrl);viewer.setAttribute('width','100%');viewer.setAttribute('height','330px');viewer.setAttribute('background','#f1f5ed');viewer.setAttribute('padding','18');viewer.setAttribute('autoplay','false');viewer.setAttribute('loop','false');viewer.setAttribute('aria-label','Experimental ASL signing motion');
  // Once Play signing is pressed, the following sections play on their own.
  viewer.addEventListener('ended$',()=>{if(signContinuous&&isCurrent()&&signingIndex+1<signingParts.length)setTimeout(()=>{if(signContinuous&&isCurrent())signInline(signingIndex+1)},350);else if(isCurrent()){signContinuous=false;$('.sign-loading',stage).textContent='Finished. Press Play signing to watch again.'}});
  const rendered=new Promise(resolve=>viewer.addEventListener('firstRender$',resolve,{once:true}));mount.appendChild(viewer);
