function dictate(){const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){toast('Dictation is not supported by this browser. Paste a transcript instead.');return}if(recognition){recognition.stop();recognition=null;return}recognition=new Recognition();recognition.lang={en:'en-ZA',zu:'zu-ZA',nso:'nso-ZA'}[$('#edit-language').value];recognition.interimResults=false;recognition.continuous=true;const target=$('#dictation-status');target.textContent='Listening… Click Dictate again to stop. Browser language support varies.';recognition.onresult=e=>{for(let i=e.resultIndex;i<e.results.length;i++)if(e.results[i].isFinal)$('#edit-transcript').value+=' '+e.results[i][0].transcript};recognition.onerror=e=>{target.textContent=`Dictation unavailable: ${e.error}. You can paste the text instead.`};recognition.onend=()=>{recognition=null;if(target.textContent.startsWith('Listening'))target.textContent='Dictation stopped. Save changes to keep your transcript.'};recognition.start()}
const actions={import:openImport,asl:openASL,'sign-inline':()=>signInline(0),'sign-next':()=>signInline(signingIndex+1),'sign-previous':()=>signInline(signingIndex-1),'sign-retry':()=>signInline(signingIndex),'pose-play':()=>{const p=$('pose-viewer');if(p){signContinuous=true;if(p.ended)p.currentTime=0;p.play();$('.sign-loading').textContent=`Signing section ${signingIndex+1} of ${signingParts.length}`}},'pose-pause':()=>{signContinuous=false;$('pose-viewer')?.pause()},copy:()=>copyText(activeRecord?.text||''),'studio-copy':()=>copyText($('#studio-text').value),stop:stopVoice,speak:readAloud,'transcribe-recording':transcribeRecording,publish:()=>{if(role!=='teacher'||!activeRecord)return;if(!activeRecord.text&&!activeRecord.published){toast('Add and review a transcript before publishing.');return}activeRecord.published=!activeRecord.published;save();route();toast(activeRecord.published?'Published to the local student view.':'Lesson moved back to drafts.');},'save-notes':()=>{activeRecord.notes=$('#lesson-notes').value;if(save())toast('Your notes are saved.');},'save-transcript':()=>{if(role!=='teacher')return;const title=$('#edit-title').value.trim();if(!title){toast('The lesson needs a title.');return}activeRecord.title=title;activeRecord.text=$('#edit-transcript').value.trim();activeRecord.language=$('#edit-language').value;if(!activeRecord.text)activeRecord.published=false;if(save()){currentTab='transcript';route();toast('Changes saved.');}},download:()=>{if(!activeRecord?.text){toast('Add a transcript first.');return}const blob=new Blob([`${activeRecord.title}\n${languages[activeRecord.language]}\n\n${activeRecord.text}`],{type:'text/plain;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=activeRecord.title.replace(/[^\p{L}\p{N} -]/gu,'').slice(0,70)+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);},dictate,delete:()=>{if(role!=='teacher'||!confirm('Delete this material from this device?'))return;const id=activeRecord.id;materials=materials.filter(m=>m.id!==id);save();db().then(d=>{const tx=d.transaction('files','readwrite');tx.objectStore('files').delete(id);tx.objectStore('files').delete(`${id}-sign`)}).catch(()=>{});location.hash='library';toast('Material deleted.');},'save-gloss':()=>{if(role!=='teacher'||!activeRecord)return;const english=lessonEnglish(activeRecord),text=$('#asl-gloss-edit').value.trim();if(!text){delete activeRecord.aslGloss}else{if(!parseGlossLines(text).length){toast('Add at least one sign.');return}activeRecord.aslGloss={source:english,text}}if(save()){signingText='';route();toast(text?'ASL gloss saved. The preview now signs your version.':'Back to the automatic ASL gloss.')}},'reset-gloss':()=>{if(role!=='teacher'||!activeRecord)return;delete activeRecord.aslGloss;if(save()){signingText='';route();toast('Back to the automatic ASL gloss.')}},'remove-sign':()=>{if(role!=='teacher')return;activeRecord.hasSignVideo=false;save();db().then(d=>d.transaction('files','readwrite').objectStore('files').delete(`${activeRecord.id}-sign`));route();toast('Attached video removed.');}};
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]');if(action){try{actions[action.dataset.action]?.()}catch(err){toast(err.message||'This action could not be completed.')}return}const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;route();return}const tab=e.target.closest('[data-tab]');if(tab){currentTab=tab.dataset.tab;route();return}const mode=e.target.closest('[data-import]');if(mode)setImportMode(mode.dataset.import);if(e.target.closest('.close-dialog')){if(busy){toast('Wait for the import to finish.');return}e.target.closest('dialog').close()}});
