document.addEventListener('change',async e=>{if(e.target.id==='pose-rate'){signRate=Number(e.target.value);$('pose-viewer').playbackRate=signRate}if(e.target.id==='voice-language'&&activeRecord){stopVoice();readingLanguage=e.target.value;currentTab='transcript';route()}if(e.target.id==='studio-material'){const m=materials.find(m=>m.id===e.target.value);if(m&&m.language==='en'){studioText=m.text;$('#studio-text').value=studioText}else if(m){$('#studio-text').value='';$('#studio-text').placeholder=`Translating “${m.title}” from ${languages[m.language]} into English…`;try{studioText=await ensureTranslation(m,'en');if($('#studio-text')){$('#studio-text').value=studioText;$('#studio-text').placeholder=''}}catch(error){toast(error.message)}}}if(e.target.id==='sign-upload'){const f=e.target.files[0];if(!f)return;if(role!=='teacher')return;if(!['video/mp4','video/webm'].includes(f.type)||f.size>25*1024*1024){toast('Choose an MP4 or WebM video smaller than 25 MB.');return}try{await fileStore(`${activeRecord.id}-sign`,f);activeRecord.hasSignVideo=true;save();route();toast('Interpreter video attached.')}catch{toast('Could not store this video. Check available browser storage.')}}});
$('#role').addEventListener('change',e=>{role=e.target.value;$('#profile-role').textContent=`${role==='teacher'?'Teacher':'Student'} workspace`;currentTab='transcript';route();toast(`${role==='teacher'?'Teacher':'Student'} demo view. No account change is made.`)});
